PROGRAM AlarmLatch
VAR_INPUT
    Fault AT %I0.0 : BOOL;
    Ack AT %I0.1 : BOOL;
END_VAR
VAR_OUTPUT
    SetFirst AT %Q0.0 : BOOL;
    ResetFirst AT %Q0.1 : BOOL;
END_VAR
VAR
    SetLatch : SR;
    ResetLatch : RS;
END_VAR

        CAL   SetLatch(S1 := Fault, R := Ack)
        LD    SetLatch.Q1
        ST    SetFirst
        CAL   ResetLatch(S := Fault, R1 := Ack)
        LD    ResetLatch.Q1
        ST    ResetFirst
END_PROGRAM

PROGRAM AlarmLatch
VAR_INPUT
    Fault AT %I0.0 : BOOL;
    Ack AT %I0.1 : BOOL;
END_VAR
VAR_OUTPUT
    SetFirst AT %Q0.0 : BOOL;
    ResetFirst AT %Q0.1 : BOOL;
END_VAR

        LD    Fault
        ST    SetFirst
        ST    ResetFirst
END_PROGRAM
